"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["24058"],{63718(e){e.exports=JSON.parse('{"id":"FIN-656","slug":"dividend-payout-ratio","term":"Dividend Payout Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The dividend payout ratio is the proportion of a company\'s net income that it pays out to shareholders as dividends, usually expressed as a percentage.","explanation":["The payout ratio shows how much of its profit a company returns to shareholders and how much it keeps to reinvest in the business or strengthen its finances.","For example, a company with net income of 100 million that pays dividends of 40 million has a payout ratio of 40%. It retains the other 60% for reinvestment.","Payout ratios vary by company and industry. Mature, stable businesses with limited growth opportunities, such as utilities, often pay out a large share of their profits. Fast-growing companies often pay low or no dividends, preferring to reinvest in expansion.","The ratio helps investors judge how sustainable a dividend is. A payout ratio above 100% means the company is paying more in dividends than it earns, which cannot continue for long unless profits recover. A very high ratio may signal that the dividend is at risk of being cut if profits fall.","Some investors prefer to compare dividends with free cash flow rather than net income, because dividends are paid in cash and accounting profit can differ from the cash a business generates."],"note":"","total":1725,"prev":{"slug":"dividend-discount-model","term":"Dividend Discount Model (DDM)"},"next":{"slug":"dividend-policy","term":"Dividend Policy"}}')}}]);